def solve(line):
    """Parse a CSV line into a list of fields.
    - Fields may be unquoted or quoted with double quotes.
    - Inside quoted fields, commas are literal and a pair of double quotes represents a single quote.
    - Empty line returns [''].
    - Trailing commas represent empty fields.
    """
    if line == "":
        return [""]
    n = len(line)
    i = 0
    fields = []
    while i < n:
        if line[i] == '"':
            # quoted field
            i += 1  # skip opening quote
            field_chars = []
            while i < n:
                ch = line[i]
                if ch == '"':
                    # possible escaped quote
                    if i + 1 < n and line[i + 1] == '"':
                        field_chars.append('"')
                        i += 2
                    else:
                        i += 1  # closing quote
                        break
                else:
                    field_chars.append(ch)
                    i += 1
            # Skip any spaces after closing quote before the delimiter
            while i < n and line[i] == ' ':
                i += 1
            # If there's a comma, consume it
            if i < n and line[i] == ',':
                i += 1
            fields.append(''.join(field_chars))
        else:
            # unquoted field
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])
            if i < n and line[i] == ',':
                i += 1
    # Handle trailing comma implying an empty field
    if line and line[-1] == ',':
        fields.append('')
    return fields

