    ``end`` >= ``start``. Meetings that touch at endpoints are allowed.
    Invalid meetings (where end < start) are ignored.
    """
    if not meetings:
        return 0
    # Filter out malformed meetings and ensure we have two numeric values
    filtered = []
    for m in meetings:
        try:
            start, end = m[0], m[1]
        except Exception:
            continue
        if end < start:
            continue
        filtered.append((start, end))
    if not filtered:
        return 0
    # Sort by end time; for equal end times, sort by start time (ascending)
    filtered.sort(key=lambda x: (x[1], x[0]))
    count = 0
    last_end = -float('inf')
    for start, end in filtered:
        if start >= last_end:
            count += 1
            last_end = end
    return count

