    last_index = {}
    start = 0
    max_len = 0
    for i, ch in enumerate(s):
        # Use a hashable key if possible, else fallback to the object's id
        try:
            key = ch
            hash(key)
        except Exception:
            key = id(ch)
        if key in last_index and last_index[key] >= start:
