def solve(matrix):
    # Determinant of square integer matrix, empty matrix returns 1
    if not matrix:
        return 1
    n = len(matrix)
    # Verify square
    for row in matrix:
        if len(row) != n:
            raise ValueError('Not a square matrix')
    # Recursive expansion (cofactor) - suitable for small n
    def det(mat):
        size = len(mat)
        if size == 1:
            return mat[0][0]
        if size == 2:
            return mat[0][0]*mat[1][1] - mat[0][1]*mat[1][0]
        total = 0
        for col in range(size):
            # build submatrix excluding row0 and col
            sub = [row[:col] + row[col+1:] for row in mat[1:]]
            sign = -1 if col % 2 else 1
            total += sign * mat[0][col] * det(sub)
        return total
    return det(matrix)

