def solve(meetings):
    """Return the maximum number of non-overlapping meetings.
    - Each meeting is a pair [start, end] with end >= start.
    - Meetings may touch at endpoints (end == next start) except when the meeting is zero-length.
      Zero-length meetings are considered to occupy a point; thus two zero-length meetings at the same time cannot both be attended,
      and a zero-length meeting cannot be attended if another meeting ends exactly at its start.
    - Invalid meetings where end < start are ignored.
    """
    if not meetings:
        return 0
    # Filter valid meetings
    valid = []
    for m in meetings:
        try:
            s, e = m[0], m[1]
        except Exception:
            continue
        if e < s:
            continue
        valid.append((s, e))
    if not valid:
        return 0
    # Sort by end, then start
    valid.sort(key=lambda x: (x[1], x[0]))
    count = 0
    last_end = -float('inf')
    for s, e in valid:
        if s == e:
            # zero-length: require strict greater than last_end
            if s > last_end:
                count += 1
                last_end = e
        else:
            if s >= last_end:
                count += 1
                last_end = e
    return count

