def solve(matrix):
    """Return the determinant of a square integer matrix.
    Empty matrix has determinant 1.
    Uses the fraction-free Bareiss algorithm for O(n^3) exact integer arithmetic.
    """
    if not matrix:
        return 1
    n = len(matrix)
    # Verify square
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Make a copy of matrix as mutable list of lists of ints
    A = [list(map(int, row)) for row in matrix]
    # Bareiss algorithm
    det = 1
    for k in range(n - 1):
        # Find pivot; if zero, swap with a lower row
        if A[k][k] == 0:
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    A[k], A[i] = A[i], A[k]
                    det = -det
                    break
            else:
                return 0
        pivot = A[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Compute new entry without fractions
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // (A[k - 1][k - 1] if k > 0 else 1)
        # Zero out column below pivot
        for i in range(k + 1, n):
            A[i][k] = 0
    # Last diagonal element is determinant
    det *= A[n - 1][n - 1]
    return det

